const D = { wind:.5, scale:1, speed:1, density:.5, energy:.6, hue:210, x:.5, y:.5, pole:'left', style:'weave', act:'breeze', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const u = Math.min(width, height);
const st = P.style;
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
const clamp = (v,a,b)=> v<a?a:(v>b?b:v);
const skyKey = width+'x'+height+'|'+P.seed+'|'+st+'|'+Math.round(P.hue);

// --- cached full-bleed sky backdrop (static) ---
if (!S.sky || S.skyKey !== skyKey){
  S.skyKey = skyKey;
  const g = createGraphics(width,height);
  g.colorMode(HSB,360,100,100,100);
  g.noStroke();
  const dark = (st==='wireframe')?1:0;
  const topH=(P.hue+165)%360, botH=(P.hue+195)%360;
  for (let y=0;y<height;y+=2){
    const t=y/height;
    g.fill((topH*(1-t)+botH*t)%360, 20+16*t, dark?(9+8*t):(26+20*(1-t)), 100);
    g.rect(0,y,width,2);
  }
  for (let i=0;i<7;i++){
    const cx=fr(i*3+1)*width, cy=fr(i*3+2)*height*0.55, cr=(0.06+fr(i*3+3)*0.13)*u;
    g.fill(0,0,100,dark?3:7);
    g.ellipse(cx,cy,cr*2.6,cr*1.1);
  }
  S.sky=g;
}
image(S.sky,0,0);

// --- flag frame ---
const horiz = (P.pole!=='top');
const Wf = (horiz?0.60:0.42)*u*P.scale;
const Hf = (horiz?0.40:0.58)*u*P.scale;
const x0 = P.x*width - Wf*0.5 + (P.pole==='left'? Wf*0.06:0);
const y0 = P.y*height - Hf*0.5;
const cols = Math.floor(12 + P.density*18);
const rows = Math.floor(8 + P.density*10);

// --- wind (real-time gust envelope on top of steady breeze; audio adds) ---
let spd = P.speed, wmul;
if (P.act==='gust'){ wmul = 0.7 + 1.1*Math.max(0,Math.sin(K.t*0.22)) + K.pulse*0.4; }
else if (P.act==='storm'){ wmul = 1.5 + 0.5*Math.sin(K.t*0.5); spd*=1.3; }
else { wmul = 0.85 + 0.35*Math.sin(K.t*0.18); }
const W = (0.08 + P.wind*0.9)*wmul + A.bass*0.35*P.wind;
const t = K.t;

// --- deform grid every frame (procedural traveling-wave cloth) ---
const pts = S.pts || (S.pts=[]);
let idx=0;
for (let j=0;j<=rows;j++) for (let i=0;i<=cols;i++){
  const gu=i/cols, gv=j/rows;
  const axis = horiz?gu:gv, cross = horiz?gv:gu;
  const flap = axis*axis*0.7 + axis*0.3;
  const ph = axis*2.3 - t*0.9*spd;
  const wave = Math.sin(ph*TWO_PI + cross*1.6) + 0.5*Math.sin(ph*2.1*TWO_PI - cross*1.1 + t*0.4);
  const z = wave*W*flap;
  const shade = Math.cos(ph*TWO_PI + cross*1.6);
  let sx = x0 + gu*Wf, sy = y0 + gv*Hf;
  if (horiz){ sy += z*0.17*Hf; sx -= Math.abs(z)*0.05*Wf; }
  else { sx += z*0.17*Wf; sy -= Math.abs(z)*0.04*Hf; }
  const p = pts[idx] || (pts[idx]={});
  p.x=sx; p.y=sy; p.gu=gu; p.gv=gv; p.sh=shade;
  idx++;
}
const at = (i,j)=>pts[j*(cols+1)+i];

const baseCol = (gu,gv)=>{
  if (st==='stripes'){ const k=Math.floor(gv*7)%2; return k?[P.hue,60,82]:[(P.hue+8)%360,20,96]; }
  if (st==='rising_sun'){ const ang=Math.atan2(gv-0.5,gu+0.03); const k=Math.floor((ang+PI)/(PI/7))%2; return k?[P.hue,82,88]:[(P.hue+25)%360,8,98]; }
  if (st==='checker'){ const k=(Math.floor(gu*6)+Math.floor(gv*6))%2; return k?[P.hue,62,84]:[(P.hue+185)%360,22,92]; }
  return [P.hue,42+P.energy*22,80]; // weave (fold-shaded solid, no outline)
};

if (st==='wireframe'){
  strokeWeight(Math.max(1,u*0.0016)); noFill();
  for (let j=0;j<=rows;j++){ beginShape(); for(let i=0;i<=cols;i++){const p=at(i,j); stroke((P.hue+p.gu*40)%360,70,clamp(60+35*p.sh,20,98),85); vertex(p.x,p.y);} endShape(); }
  for (let i=0;i<=cols;i++){ beginShape(); for(let j=0;j<=rows;j++){const p=at(i,j); stroke((P.hue+p.gu*40)%360,60,clamp(52+30*p.sh,20,98),50); vertex(p.x,p.y);} endShape(); }
} else if (st==='halftone'){
  noStroke();
  const cw=Wf/cols, ch=Hf/rows;
  for (let j=0;j<rows;j++) for (let i=0;i<cols;i++){
    const p=at(i,j); const sh=(p.sh+1)*0.5; const r=(0.28+sh*0.92)*cw;
    const col=baseCol(p.gu,p.gv);
    fill(col[0],55,clamp(28+sh*66,10,98),95);
    ellipse(p.x+cw*0.5, p.y+ch*0.5, r, r);
  }
} else {
  noStroke();
  for (let j=0;j<rows;j++) for (let i=0;i<cols;i++){
    const a=at(i,j), b=at(i+1,j), c=at(i+1,j+1), d=at(i,j+1);
    const gu=(a.gu+c.gu)*0.5, gv=(a.gv+c.gv)*0.5;
    const col=baseCol(gu,gv);
    const sh=(a.sh+b.sh+c.sh+d.sh)*0.25;
    const lit=0.66+0.5*P.energy*sh;
    fill(col[0], col[1], clamp(col[2]*lit,5,99), 100);
    beginShape(); vertex(a.x,a.y); vertex(b.x,b.y); vertex(c.x,c.y); vertex(d.x,d.y); endShape(CLOSE);
  }
}

// --- pole (optional, static prop) ---
if (P.pole!=='none'){
  push(); noStroke();
  const pw=Math.max(2,u*0.012);
  if (P.pole==='top'){
    fill(0,0,52); rect(x0-pw*0.5, y0-pw, Wf+pw, pw*1.4);
    fill(0,0,78); ellipse(x0, y0-pw*0.3, pw*2.2, pw*2.2);
  } else {
    const pxp=x0-pw*0.2;
    fill(0,0,48); rect(pxp-pw*0.5, y0-Hf*0.12, pw, Hf*1.22);
    fill(0,0,80); ellipse(pxp, y0-Hf*0.12, pw*2.4, pw*2.4);
  }
  pop();
}
